1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Computes a single Luhn check digit over the digits contained in a string.
5	 *
6	 * <p>The standard Luhn algorithm scans the input right-to-left over its digit
7	 * characters (any non-digit is ignored), doubling every second digit and subtracting
8	 * 9 from any doubled value greater than 9, then sums the results. The check digit is
9	 * the amount that would bring that sum to the next multiple of ten, i.e.
10	 * {@code (10 - (sum % 10)) % 10}, always a value from 0 to 9.
11	 */
12	public final class LuhnCheckDigit {
13	
14	    private LuhnCheckDigit() {
15	    }
16	
17	    /**
18	     * Compute the Luhn check digit over the digits contained in {@code s}.
19	     *
20	     * @param s the source string (only its digit characters are considered)
21	     * @return the Luhn check digit, a value from 0 to 9
22	     */
23	    public static int compute(String s) {
24	        int sum = 0;
25	        boolean dbl = true;
26	        for (int i = s.length() - 1; i >= 0; i--) {
27	            char c = s.charAt(i);
28	            if (c < '0' || c > '9') {
29	                continue;
30	            }
31	            int d = c - '0';
32	            if (dbl) {
33	                d *= 2;
34	                if (d > 9) {
35	                    d -= 9;
36	                }
37	            }
38	            sum += d;
39	            dbl = !dbl;
40	        }
41	        return (10 - (sum % 10)) % 10;
42	    }
43	}
