1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Validates an owner's 'postcode' against the owner's city.
5	 *
6	 * <p>A postcode is validated ONLY when present; a {@code null} postcode is always accepted,
7	 * keeping the request contract backward-compatible. When present it is expected to be four
8	 * digits (enforced by the request schema) and must fall within the inclusive range reserved
9	 * for the city's region per the fixed table:
10	 * <ul>
11	 *   <li>NSW: 2000-2099</li>
12	 *   <li>VIC: 3000-3099</li>
13	 *   <li>QLD: 4000-4099</li>
14	 * </ul>
15	 * The region is derived from the city via {@link LocalityResolver}, and the range reserved
16	 * for that region is sourced from {@link LocalityResolver#postcodeRange} (the single source
17	 * of truth for the region&harr;postcode relationship). A city with no known region (locality
18	 * {@code 'UNKNOWN'}) accepts any 4-digit postcode.
19	 */
20	public final class PostcodeValidator {
21	
22	    private PostcodeValidator() {
23	    }
24	
25	    /**
26	     * Validate a postcode for a city, throwing when the postcode is out of range for the
27	     * city's region.
28	     *
29	     * @param city     the owner's city (used to derive the region)
30	     * @param postcode the supplied postcode, or {@code null} when none was given
31	     * @throws InvalidPostcodeException if a 4-digit postcode is present but falls outside the
32	     *         inclusive range reserved for the city's region.
33	     */
34	    public static void validate(String city, String postcode) {
35	        if (postcode == null) {
36	            return;
37	        }
38	        int[] range = LocalityResolver.postcodeRange(LocalityResolver.resolve(city));
39	        if (range == null) {
40	            return;
41	        }
42	        int value = Integer.parseInt(postcode);
43	        if (value < range[0] || value > range[1]) {
44	            throw new InvalidPostcodeException(postcode, city);
45	        }
46	    }
47	}
