1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's 'locality' (canonical region) from the postcode and city.
7	 *
8	 * <p>The region is resolved by the postcode range first
9	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), and only
10	 * falls back to the fixed city-to-region table ({@code Sydney -> NSW},
11	 * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) when the postcode is absent or
12	 * in no known range. Preferring the postcode returns the same region for known cities
13	 * but disambiguates cities that share a name.
14	 *
15	 * <p>A city not covered by either lookup (or a {@code null} city with no matching
16	 * postcode) resolves to {@code 'UNKNOWN'}.
17	 */
18	public final class LocalityResolver {
19	
20	    /** City -> canonical region. Cities not listed derive locality 'UNKNOWN'. */
21	    private static final Map<String, String> CITY_REGION = Map.of(
22	        "Sydney", "NSW",
23	        "Melbourne", "VIC",
24	        "Brisbane", "QLD");
25	
26	    /**
27	     * Region -> inclusive 4-digit postcode range {low, high}. This is the single source of
28	     * truth for the region&harr;postcode relationship, read both here (postcode -> region)
29	     * and by {@link PostcodeValidator} (region -> range, via {@link #postcodeRange}).
30	     */
31	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
32	        "NSW", new int[] {2000, 2099},
33	        "VIC", new int[] {3000, 3099},
34	        "QLD", new int[] {4000, 4099});
35	
36	    /** Locality returned when neither the postcode nor the city resolves a region. */
37	    private static final String UNKNOWN = "UNKNOWN";
38	
39	    private LocalityResolver() {
40	    }
41	
42	    /**
43	     * Resolve the canonical region for a city, using the city-to-region table only.
44	     *
45	     * @param city the owner's city (any value)
46	     * @return the canonical region string, or {@code 'UNKNOWN'} when the city is not
47	     *         in the table.
48	     */
49	    public static String resolve(String city) {
50	        return CITY_REGION.getOrDefault(city, UNKNOWN);
51	    }
52	
53	    /**
54	     * Resolve the canonical region, preferring the postcode over the city. The region
55	     * is looked up by postcode range first; when the postcode is absent or in no known
56	     * range, the city-to-region table is used as a fallback.
57	     *
58	     * @param city     the owner's city (used as a fallback)
59	     * @param postcode the owner's postcode, or {@code null} when none was given
60	     * @return the canonical region string, or {@code 'UNKNOWN'} when neither lookup
61	     *         resolves a region.
62	     */
63	    public static String resolve(String city, String postcode) {
64	        String fromPostcode = resolveByPostcode(postcode);
65	        return fromPostcode != null ? fromPostcode : resolve(city);
66	    }
67	
68	    /**
69	     * The inclusive 4-digit postcode range {@code {low, high}} reserved for a region, or
70	     * {@code null} when the region has no reserved range. Exposes the single-sourced
71	     * {@code REGION_POSTCODES} table for {@link PostcodeValidator}.
72	     *
73	     * @param region a canonical region string (e.g. {@code 'NSW'})
74	     * @return a defensive copy of the {@code {low, high}} range, or {@code null} if none
75	     */
76	    static int[] postcodeRange(String region) {
77	        int[] range = REGION_POSTCODES.get(region);
78	        return range == null ? null : range.clone();
79	    }
80	
81	    /** Region whose range contains the postcode, or {@code null} if none (or unparseable). */
82	    private static String resolveByPostcode(String postcode) {
83	        if (postcode == null) {
84	            return null;
85	        }
86	        int value;
87	        try {
88	            value = Integer.parseInt(postcode.trim());
89	        }
90	        catch (NumberFormatException e) {
91	            return null;
92	        }
93	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
94	            int[] range = entry.getValue();
95	            if (value >= range[0] && value <= range[1]) {
96	                return entry.getKey();
97	            }
98	        }
99	        return null;
100	    }
101	}
