16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    /**
72	     * The current number of owners that belong to this owner's household (owners sharing the same
73	     * {@code householdId}, including this one). Not persisted: it is populated from the current data
74	     * whenever the owner is loaded or saved.
75	     */
76	    @Transient
77	    private Integer householdMemberCount;
78	
79	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
80	    private Set<Pet> pets;
81	
82	    public String getAddress() {
83	        return this.address;
84	    }
85	
86	    public void setAddress(String address) {
87	        this.address = address;
88	    }
89	
90	    public String getCity() {
91	        return this.city;
92	    }
93	
94	    public void setCity(String city) {
95	        this.city = city;
96	    }
97	
98	    public String getPostcode() {
99	        return this.postcode;
100	    }
101	
102	    public void setPostcode(String postcode) {
103	        this.postcode = postcode;
104	    }
105	
106	    public String getTelephone() {
107	        return this.telephone;
108	    }
109	
110	    public void setTelephone(String telephone) {
111	        this.telephone = telephone;
112	    }
113	
114	    public String getEmail() {
115	        return this.email;
116	    }
117	
118	    public void setEmail(String email) {
119	        this.email = email;
120	    }
121	
122	    public LocalDate getRegistrationDate() {
123	        return this.registrationDate;
124	    }
125	
126	    public void setRegistrationDate(LocalDate registrationDate) {
127	        this.registrationDate = registrationDate;
128	    }
129	
130	    public String getCustomerCode() {
131	        return this.customerCode;
132	    }
133	
134	    public void setCustomerCode(String customerCode) {
135	        this.customerCode = customerCode;
136	    }
137	
138	    public String getHouseholdId() {
139	        return this.householdId;
140	    }
141	
142	    public void setHouseholdId(String householdId) {
143	        this.householdId = householdId;
144	    }
145	
146	    public Integer getNamesakeCount() {
147	        return this.namesakeCount;
148	    }
149	
150	    public void setNamesakeCount(Integer namesakeCount) {
151	        this.namesakeCount = namesakeCount;
152	    }
153	
154	    public Integer getHouseholdMemberCount() {
155	        return this.householdMemberCount;
156	    }
157	
158	    public void setHouseholdMemberCount(Integer householdMemberCount) {
159	        this.householdMemberCount = householdMemberCount;
160	    }
161	
162	    /**
163	     * The owner's derived identity key, {@code normalizedTelephone + '|' + (email or empty) + '|' +
164	     * (householdId or empty)}. This single key is the sole criterion for duplicate detection on
165	     * creation: a new owner is rejected with 409 only when its whole identity key equals an existing
166	     * owner's. Because the telephone is part of the key, two members of the same household (same
167	     * {@code householdId}) with different telephones have distinct identity keys and are both
168	     * allowed; only an exact full-key match is a duplicate. The telephone and email components are
169	     * already held in their normalized forms (canonical E.164 and lower-cased) on every write path,
170	     * so the key is comparable across owners. Not persisted: it is computed from the current fields.
171	     */
172	    @Transient
173	    public String getIdentityKey() {
174	        String telephoneOrEmpty = this.telephone == null ? "" : this.telephone;
175	        String emailOrEmpty = this.email == null ? "" : this.email;
176	        String householdOrEmpty = this.householdId == null ? "" : this.householdId;
177	        return telephoneOrEmpty + "|" + emailOrEmpty + "|" + householdOrEmpty;
178	    }
179	
180	    /**
181	     * Stamp the owner's registration date with the server's current date on first
182	     * persist when none was supplied, so the default applies on every create path.
183	     */
184	    @PrePersist
185	    protected void onCreate() {
186	        if (this.registrationDate == null) {
187	            this.registrationDate = LocalDate.now();
188	        }
189	    }
190	
191	    protected Set<Pet> getPetsInternal() {
192	        if (this.pets == null) {
193	            this.pets = new HashSet<>();
194	        }
195	        return this.pets;
196	    }
197	
198	    protected void setPetsInternal(Set<Pet> pets) {
199	        this.pets = pets;
200	    }
201	
202	    public List<Pet> getPets() {
203	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
204	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
205	        return Collections.unmodifiableList(sortedPets);
206	    }
207	
208	    public void setPets(List<Pet> pets) {
209	        this.pets = new HashSet<>(pets);
210	    }
211	
212	    public void addPet(Pet pet) {
213	        getPetsInternal().add(pet);
214	        pet.setOwner(this);
215	    }
216	
217	    /**
218	     * Return the Pet with the given name, or null if none found for this Owner.
219	     *
220	     * @param name to test
221	     * @return true if pet name is already in use
222	     */
223	    public Pet getPet(String name) {
224	        return getPet(name, false);
225	    }
226	
227	    /**
228	     * Return the Pet with the given name, or null if none found for this Owner.
229	     *
230	     * @param name to test
231	     * @return true if pet name is already in use
232	     */
233	    public Pet getPet(String name, boolean ignoreNew) {
234	        name = name.toLowerCase();
235	        for (Pet pet : getPetsInternal()) {
236	            if (!ignoreNew || !pet.isNew()) {
237	                String compName = pet.getName();
238	                compName = compName.toLowerCase();
239	                if (compName.equals(name)) {
240	                    return pet;
241	                }
242	            }
243	        }
244	        return null;
245	    }
246	
247	    public Pet getPet(Integer petId) {
248	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
249	    }
250	
251	    @Override
252	    public String toString() {
253	        return new ToStringCreator(this)
254	
255	            .append("id", this.getId())
256	            .append("new", this.isNew())
257	            .append("lastName", this.getLastName())
258	            .append("firstName", this.getFirstName())
259	            .append("address", this.address)
260	            .append("city", this.city)
261	            .append("telephone", this.telephone)
262	            .toString();
263	    }
264	}
