270	    /**
271	     * Count the existing owners (before this create) that share the given first and last name,
272	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
273	     */
274	    private int countNamesakes(String firstName, String lastName) {
275	        if (firstName == null || lastName == null) {
276	            return 0;
277	        }
278	        return (int) ownerRepository.findAll().stream()
279	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
280	                && lastName.equalsIgnoreCase(owner.getLastName()))
281	            .count();
282	    }
