284	    /**
285	     * Build a customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3}
286	     * is the upper-cased first three letters of the owner's city, {@code LAST3} the
287	     * upper-cased first three letters of the owner's last name and {@code NNNN} a per-city,
288	     * 4-digit zero-padded sequence equal to one more than the current number of owners
289	     * already in that city (e.g. {@code 'LON-SMI-0007'}).
290	     */
291	    private String generateCustomerCode(String city, String lastName) {
292	        String cityName = city == null ? "" : city;
293	        String city3 = cityName.substring(0, Math.min(3, cityName.length())).toUpperCase();
294	        String name = lastName == null ? "" : lastName;
295	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
296	        long sequence = countOwnersInCity(cityName) + 1L;
297	        return String.format("%s-%s-%04d", city3, last3, sequence);
298	    }
