344	     * to the following Monday, while a weekday is returned unchanged. Applied to the effective
345	     * registration date (whether supplied or defaulted to the server date) so that the stored
346	     * {@code registrationDate}, every value derived from it (such as the membership number's year
347	     * segment) and the per-day create-limit all use the adjusted business day.
348	     */
349	    private static LocalDate toBusinessDay(LocalDate date) {
350	        DayOfWeek day = date.getDayOfWeek();
351	        if (day == DayOfWeek.SATURDAY) {
352	            return date.plusDays(2);
353	        }
354	        if (day == DayOfWeek.SUNDAY) {
355	            return date.plusDays(1);
356	        }
357	        return date;
358	    }
