372	    public String householdIdFor(String lastName, String address) throws DataAccessException {
373	        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
374	        try {
375	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
376	            StringBuilder sb = new StringBuilder(32);
377	            for (int i = 0; i < 8; i++) {
378	                sb.append(String.format("%02X", digest[i]));
379	            }
380	            return sb.toString();
381	        } catch (NoSuchAlgorithmException ex) {
382	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
383	        }
384	    }
