386	    /**
387	     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
388	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
389	     * spaced but equivalent values compare equal.
390	     */
391	    private static String normalizeHouseholdValue(String value) {
392	        if (value == null) {
393	            return "";
394	        }
395	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
396	    }
397	
398	    /**
399	     * Normalizes an address for household comparison by first applying the canonical address
400	     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
401	     * then the shared household-value normalization, so every address comparison uses the same
402	     * normalized form regardless of how the value was originally supplied.
403	     */
404	    private static String normalizeHouseholdAddress(String address) {
405	        return normalizeHouseholdValue(AddressNormalizer.normalize(address));
406	    }
407	
408	    /**
409	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
410	     * owners that share its {@code householdId}. Owners without a household id are left at a count
411	     * of zero.
412	     *
413	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
414	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
415	     */
416	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
417	        if (!owners.isEmpty()) {
418	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
419	                .filter(owner -> owner.getHouseholdId() != null)
420	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
421	            for (Owner owner : owners) {
422	                long size = owner.getHouseholdId() == null
423	                    ? 0L
424	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
425	                owner.setHouseholdMemberCount((int) size);
426	            }
427	        }
428	        return result;
429	    }
430	
431	    /**
432	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
433	     */
434	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
435	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
436	    }
