17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.samples.petclinic.util.PostcodeValidator;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
102	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
103	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
112	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
113	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
114	        }
115	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
116	        if (sharesHousehold) {
117	            owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getAddress()));
118	        }
119	        // All duplicate detection is consolidated into the single derived identity key: reject only
120	        // when the new owner's whole identity key (telephone|email|householdId) matches an existing one.
121	        if (this.clinicService.isIdentityKeyInUse(owner)) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        this.clinicService.saveOwner(owner);
128	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
129	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
130	            ownerMapper.formatMembershipLevel(owner));
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
133	        headers.setLocation(UriComponentsBuilder.newInstance()
134	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
135	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
141	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
142	        if (currentOwner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
146	        currentOwner.setAddress(ownerFieldsDto.getAddress());
147	        currentOwner.setCity(ownerFieldsDto.getCity());
148	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
149	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
150	        currentOwner.setLastName(ownerFieldsDto.getLastName());
151	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
152	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
153	        this.clinicService.saveOwner(currentOwner);
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Transactional
159	    @Override
160	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        this.clinicService.deleteOwner(owner);
166	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        HttpHeaders headers = new HttpHeaders();
177	        Pet pet = petMapper.toPet(petFieldsDto);
178	        owner.setId(ownerId);
179	        pet.setOwner(owner);
180	        pet.getType().setName(null);
181	        this.clinicService.savePet(pet);
182	        PetDto petDto = petMapper.toPetDto(pet);
183	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
184	            .buildAndExpand(pet.getId()).toUri());
185	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
191	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
192	        if (currentOwner != null) {
193	            Pet currentPet = this.clinicService.findPetById(petId);
194	            if (currentPet != null) {
195	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
196	                currentPet.setName(petFieldsDto.getName());
197	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
198	                this.clinicService.savePet(currentPet);
199	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	            }
201	        }
202	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
208	        HttpHeaders headers = new HttpHeaders();
209	        Visit visit = visitMapper.toVisit(visitFieldsDto);
210	        Pet pet = new Pet();
211	        pet.setId(petId);
212	        visit.setPet(pet);
213	        this.clinicService.saveVisit(visit);
214	        VisitDto visitDto = visitMapper.toVisitDto(visit);
215	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
216	            .buildAndExpand(visit.getId()).toUri());
217	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
218	    }
219	
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner != null) {
226	            Pet pet = owner.getPet(petId);
227	            if (pet != null) {
228	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
229	            }
230	        }
231	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	    }
233	}
