    @Transactional(readOnly = true)
    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
        return specialtyRepository.findAll();
    }

    @Override
    @Transactional
    public void saveSpecialty(Specialty specialty) throws DataAccessException {
        specialtyRepository.save(specialty);
    }

    @Override
    @Transactional
    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
        specialtyRepository.delete(specialty);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<PetType> findPetTypes() throws DataAccessException {
        return petRepository.findPetTypes();
    }

    @Override
    @Transactional(readOnly = true)
    public Owner findOwnerById(int id) throws DataAccessException {
        return decorateWithHouseholdMemberCount(findEntityById(() -> ownerRepository.findById(id)));
    }

    @Override
    @Transactional(readOnly = true)
    public Pet findPetById(int id) throws DataAccessException {
        return findEntityById(() -> petRepository.findById(id));
    }

    @Override
    @Transactional
    public void savePet(Pet pet) throws DataAccessException {
        pet.setType(findPetTypeById(pet.getType().getId()));
        petRepository.save(pet);
    }

    @Override
    @Transactional
    public void saveVisit(Visit visit) throws DataAccessException {
        visitRepository.save(visit);

    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Vet> findVets() throws DataAccessException {
        return vetRepository.findAll();
    }

    @Override
    @Transactional
    public void saveOwner(Owner owner) throws DataAccessException {
        if (owner.isNew()) {
            LocalDate effectiveDate = owner.getRegistrationDate() != null
                ? owner.getRegistrationDate()
                : LocalDate.now();
            owner.setRegistrationDate(toBusinessDay(effectiveDate));
            if (owner.getCustomerCode() == null) {
                owner.setCustomerCode(generateCustomerCode(owner));
            }
            if (owner.getNamesakeCount() == null) {
                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
            }
        }
        ownerRepository.save(owner);
        decorateWithHouseholdMemberCount(owner);
    }

    /**
     * Count the existing owners (before this create) that share the given first and last name,
     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
     */
    private int countNamesakes(String firstName, String lastName) {
        if (firstName == null || lastName == null) {
            return 0;
        }
        return (int) ownerRepository.findAll().stream()
            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
                && lastName.equalsIgnoreCase(owner.getLastName()))
            .count();
    }

    /**
     * Build a customer code formatted {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
     * canonical region derived from the owner's postcode (falling back to the city-to-region
     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}) and {@code HASH8}
     * is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the owner's
     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). There
     * is no sequence number: identity is fully determined by the region and the telephone/last
     * name hash.
     */
    private String generateCustomerCode(Owner owner) {
        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
        return region + "-" + hash8(telephone + lastName);
    }

    /**
     * The first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
     * of the UTF-8 bytes of {@code value}, used as the hash segment of the customer code.
     */
    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
        }
    }

    /**
     * Count the existing owners whose city matches the given city, compared case-insensitively,
     * used to derive the per-city sequence of the customer code.
     */
    private long countOwnersInCity(String city) {
        if (city == null) {
            return 0L;
        }
        return ownerRepository.findAll().stream()
            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
            .count();
    }

    @Override
    @Transactional(readOnly = true)
    public boolean isCityAtCapacity(String city) throws DataAccessException {
        return countOwnersInCity(city) >= CITY_CAPACITY;
    }

    @Override
    @Transactional(readOnly = true)
    public boolean isDailyRegistrationAtCapacity() throws DataAccessException {
        return countRegisteredToday() >= DAILY_CAPACITY;
    }

    @Override
    @Transactional(readOnly = true)
    public boolean isBulkSignupDay() throws DataAccessException {
        return countRegisteredToday() > BULK_SIGNUP_THRESHOLD;
    }

    /**
     * Count the owners whose registration date equals today's business day, used by the
     * daily create-limit and bulk-signup rules.
     */
    private long countRegisteredToday() {
        LocalDate businessDay = toBusinessDay(LocalDate.now());
        return ownerRepository.findAll().stream()
            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
            .count();
    }

    /**
     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced
     * to the following Monday, while a weekday is returned unchanged. Applied to the effective
     * registration date (whether supplied or defaulted to the server date) so that the stored
     * {@code registrationDate}, every value derived from it (such as the membership number's year
     * segment) and the per-day create-limit all use the adjusted business day.
     */
    private static LocalDate toBusinessDay(LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        if (day == DayOfWeek.SATURDAY) {
            return date.plusDays(2);
        }
        if (day == DayOfWeek.SUNDAY) {
            return date.plusDays(1);
        }
        return date;
    }

    @Override
    @Transactional(readOnly = true)
    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
        String identityKey = owner.getIdentityKey();
        return ownerRepository.findAll().stream()
            .filter(existing -> existing != owner)
            .map(Owner::getIdentityKey)
            .anyMatch(identityKey::equals);
    }

    @Override
    @Transactional(readOnly = true)
    public String householdIdFor(String lastName, String address) throws DataAccessException {
        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(32);
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
        }
    }

    /**
     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
     * spaced but equivalent values compare equal.
     */
    private static String normalizeHouseholdValue(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * Normalizes an address for household comparison by first applying the canonical address
     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
     * then the shared household-value normalization, so every address comparison uses the same
     * normalized form regardless of how the value was originally supplied.
     */
    private static String normalizeHouseholdAddress(String address) {
        return normalizeHouseholdValue(AddressNormalizer.normalize(address));
    }

    /**
     * Populate each given owner's transient {@code householdMemberCount} with the current number of
     * owners that share its {@code householdId}. Owners without a household id are left at a count
     * of zero.
     *
     * <p>The household sizes are computed in a single pass over the owner table regardless of how
     * many owners are being decorated, so decorating a whole page does not re-scan per element.
     */
    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
        if (!owners.isEmpty()) {
            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
                .filter(owner -> owner.getHouseholdId() != null)
                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
            for (Owner owner : owners) {
                long size = owner.getHouseholdId() == null
                    ? 0L
                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
                owner.setHouseholdMemberCount((int) size);
            }
        }
        return result;
    }

    /**
     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
     */
    private Owner decorateWithHouseholdMemberCount(Owner owner) {
        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
        return decorateWithHouseholdMemberCount(owners, owners);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Visit> findVisitsByPetId(int petId) {
        return visitRepository.findByPetId(petId);
    }

    @Override
    @Transactional(readOnly = true)
    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
    }

    private <T> T findEntityById(Supplier<T> supplier) {
        try {
            return supplier.get();
        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
            // Just ignore not found exceptions for Jdbc/Jpa realization
            return null;
        }
    }

}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.Named;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.util.AddressNormalizer;
import org.springframework.samples.petclinic.util.LocalityResolver;
import org.springframework.samples.petclinic.util.LuhnCheckDigit;
import org.springframework.samples.petclinic.util.TelephoneNormalizer;

import java.util.Collection;
import java.util.List;
import java.util.Locale;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "formatCheckDigit")
    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "formatMembershipLevel")
    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
    @Mapping(target = "bulkSignupWarning", ignore = true)
    OwnerDto toOwnerDto(Owner owner);

    /**
     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
     * last names, as required by the API's read-only {@code displayName} field.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
     * applied only where referenced via {@code qualifiedByName}.
     */
    @Named("formatDisplayName")
    default String formatDisplayName(Owner owner) {
        if (owner == null) {
            return null;
        }
        return owner.getLastName() + ", " + owner.getFirstName();
    }

    /**
     * Formats an owner's initials as the upper-cased first letters of the first and last
     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
     * API's read-only {@code initials} field.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
     * applied only where referenced via {@code qualifiedByName}.
     */
    @Named("formatInitials")
    default String formatInitials(Owner owner) {
        if (owner == null) {
            return null;
        }
        return initial(owner.getFirstName()) + initial(owner.getLastName());
    }

    /**
     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
     * {@code customerCode} is the owner's customer code and {@code YY} is the last two
     * digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}), as required
     * by the API's read-only {@code membershipNumber} field. Returns {@code null} when
     * either the customer code or registration date is absent.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
     * applied only where referenced via {@code qualifiedByName}.
     */
    @Named("formatMembershipNumber")
    default String formatMembershipNumber(Owner owner) {
        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
    }

    /**
     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
     * code. Returns {@code null} when the customer code is absent.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
     * applied only where referenced via {@code qualifiedByName}.
     */
    @Named("formatCheckDigit")
    default Integer formatCheckDigit(Owner owner) {
        if (owner == null || owner.getCustomerCode() == null) {
            return null;
        }
        return LuhnCheckDigit.compute(owner.getCustomerCode());
    }

    /**
     * Derives an owner's membership level, as required by the API's read-only
     * {@code membershipLevel} field: starting at 1, plus 1 when an email address is present,
     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), capped at 3. (Level 4
     * is reserved for tenure.)
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
     * to record the membership level on the create audit line).
     */
    @Named("formatMembershipLevel")
    default Integer formatMembershipLevel(Owner owner) {
        if (owner == null) {
            return null;
        }
        int level = 1;
        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
            level++;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            level++;
        }
        return Math.min(level, 3);
    }

    /**
     * Derives an owner's locality, as required by the API's read-only {@code locality}
     * field: the canonical region resolved by the postcode range first
     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back
     * to the fixed city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
     * {@code Brisbane -> QLD}) when the postcode is absent or in no known range, or
     * {@code 'UNKNOWN'} when neither resolves a region.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
     * applied only where referenced via {@code qualifiedByName}.
     */
    @Named("formatLocality")
    default String formatLocality(Owner owner) {
        if (owner == null) {
            return null;
        }
        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
    }

    /**
     * Derives an owner's preferred contact channel, as required by the API's read-only
     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
     * otherwise {@code 'PHONE'}.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
     * applied only where referenced via {@code qualifiedByName}.
     */
    @Named("formatContactPreference")
    default String formatContactPreference(Owner owner) {
        if (owner == null) {
            return null;
        }
        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
    }

    private static String initial(String name) {
        if (name == null || name.isEmpty()) {
            return "";
        }
        return Character.toUpperCase(name.charAt(0)) + ".";
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
    Owner toOwner(OwnerFieldsDto ownerDto);

    /**
     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
     * {@code '12 MAIN STREET'}.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
     * only where referenced via {@code qualifiedByName}.
     */
    @Named("normalizeAddress")
    default String normalizeAddress(String address) {
        return AddressNormalizer.normalize(address);
    }

    /**
     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
     *
     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
     */
    @Named("normalizeTelephone")
    default String normalizeTelephone(String telephone) {
        return TelephoneNormalizer.toE164(telephone);
    }

    /**
     * Normalizes an email address by lower-casing it, so it is stored and returned in a
     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
     * guarantees any value present is a syntactically valid address.
     *
     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
     * applied only where referenced via {@code qualifiedByName} (and when called directly,
     * e.g. on update).
     */
    @Named("normalizeEmail")
    default String normalizeEmail(String email) {
        return email == null ? null : email.toLowerCase(Locale.ROOT);
    }

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

